% 确定各系统传递函数

G1 = tf(2,[conv([2,1],[8,1])]);

G2 = tf(200,[conv([1,1,0,0],[10,1])]);

G3 = tf(8*[10,1],[conv([1,1,1,0],[0.5,1])]);

G4 = tf(10*[0.0025,0.1,1],[conv([1,1,0],[10,1])]);

% 调用子程序绘制系统开环对数幅频渐近特性曲线

w = 10e-3:0.1:100;

[x1,y1] = bd_asymp(G1,w);

[x2,y2] = bd_asymp(G2,w);

[x3,y3] = bd_asymp(G3,w);

[x4,y4] = bd_asymp(G4,w);

figure(1); semilogx(x1,y1),grid;

figure(2); semilogx(x2,y2),grid;

figure(3); semilogx(x3,y3),grid;

figure(4); semilogx(x4,y4),grid;

function [wpos,ypos] = bd_asymp(G,w)

% 绘制伯德图渐近线

G1 = zpk(G); wpos = []; pos1 = [];

if nargin == 1, w = freqint2(G); end

zer = G1.z{1}; pol = G1.p{1}; gain = G1.k;

for i = 1:length(zer)

if isreal(zer(i))

wpos = $wpos,abs(zer(i))$;

pos1 = [pos1, 20];

else

if imag(zer(i)) > 0

wpos = $wpos,abs(zer(i))$;

pos1 = [pos1, 40];

end

end

end

for i = 1:length(pol)

if isreal(pol(i))

wpos = $wpos,abs(pol(i))$;

pos1 = $pos1, -20$;

else

if imag(pol(i)) > 0

wpos = $wpos, abs(pol(i))$;

pos1 = $pos1, -40$;

end

end

end

wpos = $wpos w(1) w(length(w))$;

pos1 = [pos1,0,0];

[wpos, ii] = sort(wpos); pos1 = pos1(ii) ;

ii = find(abs(wpos) < eps) ; kslp = 0;

w_start = 1000 * eps;

if length(ii) > 0

kslp = sum(pos1(ii));

ii = $ii(length(ii))+1$:length(wpos);

wpos = wpos(ii); pos1 = pos1(ii) ;

end

while 1

[ypos1,pp] = bode(G, w_start);

if isinf(ypos1)

w_start = w_start * 10;

else

break;

end

end

wpos = $w_start wpos$;

ypos(1) = 20 * log10(ypos1) ;

pos1 = [kslp pos1];

for i = 2:length(wpos)

kslp = sum(pos1(1:i - 1)) ;

ypos(i) = ypos(i - 1) + kslp * log10(wpos(i)/wpos(i - 1));

end

ii = find(wpos >= w(1) & wpos <= w(length(w)));

wpos = wpos(ii) ; ypos = ypos(ii);
